import React from 'react';
import { render, screen } from '@testing-library/react';
import TadaDeliveryDrinks from './TadaDeliveryDrinks';

describe('TadaDeliveryDrinks', () => {
  test('should render without crashing', () => {
    render(<TadaDeliveryDrinks />);
    expect(screen.getByTestId('TadaDeliveryDrinksIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<TadaDeliveryDrinks variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Tada Delivery Drinks Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<TadaDeliveryDrinks variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Tada Delivery Drinks Vertical Logo')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<TadaDeliveryDrinks colorType="onColorBg" />);
    expect(screen.getByTestId('TadaDeliveryDrinksIcon')).toBeInTheDocument();
  });
});
